import qs from 'qs';
export type Environment = 'dev' | 'stage' | 'live' | 'debug';

function detectEnvironment(): Environment {
    const hostname = window.location.hostname;

    const data = qs.parse(window.location.search.substr(window.location.search.indexOf('?') + 1));
    if (data && data.env !== undefined) {
        return data.env as Environment;
    }

    if (!hostname) {
        return 'debug';
    }

    switch (true) {
        case (hostname.indexOf('dev-') > -1):
            return 'dev';
        case (hostname.indexOf('stage-') > -1):
            return 'stage';
        case (hostname.indexOf('tombola') > -1):
            return 'live';
        default:
            return 'debug';
    }
}

export default detectEnvironment();
